package com.astrocare.security;
import com.astrocare.dto.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.*; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class AuthService { private final AuthenticationManager manager; private final DatabaseUserDetailsService users; private final JwtService jwt; public LoginResponse login(LoginRequest r){UserDetails u=(UserDetails)manager.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password())).getPrincipal();return new LoginResponse(jwt.generate(u),"Bearer",jwt.expiration(),u.getUsername(),u.getAuthorities().stream().map(a->a.getAuthority()).collect(java.util.stream.Collectors.toSet()));} }
